contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 drugsSeed) public payable {
        require(drugsSeed > 0);
        c.seedMarket(drugsSeed); if (__ESBMC_reverted()) return;
        c.getFreeKilo(); if (__ESBMC_reverted()) return;
        assert(c.Kilos(address(this)) == 300 && c.getMyKilo() == 300);
    }
    receive() external payable {}
}

