pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(uint256 drugsSeed) internal {
        vm.assume(drugsSeed > 0);
        try c.seedMarket(drugsSeed) {} catch { return; }
        try c.getFreeKilo() {} catch { return; }
        assertTrue(c.Kilos(address(this)) == 300 && c.getMyKilo() == 300);
    }

    function testFuzz_run(uint256 drugsSeed) public {
        _run(drugsSeed);
    }

    receive() external payable {}
}
